use std::{fs,path::Path};#[path="runtime.rs"]mod result_carry;use result_carry::*;
fn main(){let w=std::env::args().nth(1).unwrap();let w=Path::new(&w);for label in ["1289","1489"]{let d=w.join(label);let p=fs::read(d.join("players.bin")).unwrap();let a=fs::read(d.join("actors.bin")).unwrap();let b=fs::read(d.join("bindings.bin")).unwrap();let players=std::array::from_fn(|i|p[i*1805..(i+1)*1805].try_into().unwrap());let actors=std::array::from_fn(|i|a[i*200..(i+1)*200].try_into().unwrap());let bindings=std::array::from_fn(|i|if b[i*3]==0{None}else{Some((b[i*3+1],b[i*3+2]))});let map=fs::read(d.join("map.bin")).unwrap();let records:[u8;600]=fs::read(d.join("records.bin")).unwrap().try_into().unwrap();let q=plan_campaign_carry(&players,&actors,&bindings,&map,&records,0x7e,2,Some(0)).unwrap();let mut out=q.players.concat();out.extend(q.actors.concat());out.extend(&q.map);out.extend(q.records_184d7c);out.push(q.flags_after);out.extend(q.frame_after.to_le_bytes());out.push(u8::from(q.selected_actor_reset_required));out.extend(&q.retired_actors);fs::write(d.join("actual.bin"),out).unwrap();assert_eq!(q.retired_actors,[0,1]);assert!(matches!(plan_campaign_carry(&players,&actors,&bindings,&map,&records,0x7e,3,Some(0)),Err(CarryError::Mode)));let mut broken=actors;broken[0][2]=4;assert!(matches!(plan_campaign_carry(&players,&broken,&bindings,&map,&records,0x7e,2,Some(0)),Err(CarryError::ActorLink)));}}
